--
-- Table structure for table `turnos_generados`
--

DROP TABLE IF EXISTS `turnos_generados`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `turnos_generados` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `turno_id` bigint unsigned NOT NULL,
  `congregacion_id` bigint unsigned NOT NULL,
  `fecha` date NOT NULL,
  `hora_inicio` time NOT NULL,
  `hora_fin` time NOT NULL,
  `capacidad` int NOT NULL DEFAULT '3',
  `ubicacion` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `notas` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,
  `estado` enum('abierto','completo','cancelado') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'abierto',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `turno_generado_unique` (`turno_id`,`fecha`),
  KEY `turnos_generados_congregacion_id_fecha_index` (`congregacion_id`,`fecha`),
  CONSTRAINT `turnos_generados_congregacion_id_foreign` FOREIGN KEY (`congregacion_id`) REFERENCES `congregaciones` (`id`) ON DELETE CASCADE,
  CONSTRAINT `turnos_generados_turno_id_foreign` FOREIGN KEY (`turno_id`) REFERENCES `turnos` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=400 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

